S = "Hakeem Force Academy"
QS = [
(S, "Who is Data Ganj Bakhsh?", ["A Sufi saint of Lahore, Hazrat Ali Hujwiri", "A Punjabi poet of Multan", "A Mughal emperor", "A famous Urdu novelist"], 0,
 "Data Ganj Bakhsh is the title of Hazrat Ali bin Usman Al-Hujwiri, an 11th-century Sufi saint who settled in Lahore. His shrine in Lahore is one of the most visited in Pakistan.",
 "He wrote the famous Persian book on Sufism, Kashf-ul-Mahjoob.", [674]),
(S, "Who was the first Governor of Balochistan after it became a province in 1970?", ["Ghous Bakhsh Raisani", "Lt Gen Riaz Hussain", "Nawab Akbar Bugti", "Lt Gen Rahimuddin Khan"], 1,
 "Balochistan became a province on 1 July 1970 when One Unit was dissolved, and Lt Gen Riaz Hussain was its first Governor.",
 "Ghous Bakhsh Raisani, who followed him, is described as the first civilian Governor of Balochistan.", [711]),
(S, "Who served as Chief Adviser of Bangladesh's interim government from August 2024 until February 2026?", ["Tarique Rahman", "Sheikh Hasina", "Dr Muhammad Yunus", "Khaleda Zia"], 2,
 "After Sheikh Hasina left in August 2024, Nobel laureate Dr Muhammad Yunus led the interim government as Chief Adviser. His term ended when Tarique Rahman became Prime Minister on 17 February 2026.",
 "Today Bangladesh has an elected Prime Minister, Tarique Rahman, so there is no Chief Adviser now.", [677]),
(S, "On which date did Benazir Bhutto first become Prime Minister of Pakistan in 1988?", ["2 December 1988", "17 August 1988", "16 November 1988", "5 July 1988"], 0,
 "After the November 1988 elections her PPP was the largest party, and she took oath as Prime Minister on 2 December 1988.",
 "She was the first woman to lead a Muslim-majority country.", [338]),
(S, "Who became Prime Minister of Pakistan after the death of General Zia ul Haq in 1988?", ["Nawaz Sharif", "Muhammad Khan Junejo", "Benazir Bhutto", "Ghulam Ishaq Khan"], 2,
 "Zia died in a plane crash on 17 August 1988. Elections were held in November 1988 and Benazir Bhutto became Prime Minister in December 1988.",
 "Ghulam Ishaq Khan, the Senate Chairman, became acting President after Zia's death.", [650]),
(S, "Who became Prime Minister of Pakistan in April 2022 after Imran Khan lost a no-confidence vote?", ["Shehbaz Sharif", "Bilawal Bhutto Zardari", "Shahid Khaqan Abbasi", "Asif Ali Zardari"], 0,
 "Imran Khan was removed by a no-confidence vote in the National Assembly on 10 April 2022, and Shehbaz Sharif was elected Prime Minister the next day.",
 "Imran Khan was the first Pakistani Prime Minister removed through a no-confidence vote.", [648]),
(S, "In which month and year did the United States declare its independence?", ["July 1776", "June 1775", "July 1783", "December 1776"], 0,
 "The Declaration of Independence was adopted by the Continental Congress on 4 July 1776.",
 "Britain formally recognised American independence in the Treaty of Paris in 1783.", [264]),
(S, "Which law governed the constitutional setup of British India just before independence in 1947?", ["Government of India Act 1935", "Government of India Act 1858", "Indian Councils Act 1861", "Morley-Minto Reforms 1909"], 0,
 "The Government of India Act 1935 was the last major constitutional law of British India and was used with changes as Pakistan's interim constitution.",
 "Pakistan worked under the amended 1935 Act until its first Constitution came in 1956.", [512]),
(S, "Between which two values do the sine and cosine functions always lie?", ["0 and 1", "-1 and 1", "-2 and 2", "-infinity and infinity"], 1,
 "On the unit circle, sine and cosine are the y and x coordinates of a point, so they can never go below -1 or above 1.",
 "Tangent, unlike sine and cosine, has no upper or lower limit.", [166]),
(S, "Which is the biggest planet of the solar system?", ["Saturn", "Neptune", "Jupiter", "Earth"], 2,
 "Jupiter is the largest planet, with a diameter about eleven times that of Earth.",
 "Saturn is the second largest planet and is famous for its rings.", [597]),
(S, "Complete the proverb: The early bird catches the ____.", ["fish", "worm", "seed", "sun"], 1,
 "The proverb says that a person who starts early gets the best chance of success, like a bird that finds the worm first.",
 "A similar saying is Early to bed and early to rise makes a man healthy, wealthy and wise.", [358]),
(S, "Why is milk boiled before drinking?", ["To kill harmful germs", "To make it colder", "To add vitamins", "To make it sweeter"], 0,
 "Heating milk to boiling point kills harmful bacteria and makes it safe to drink.",
 "The process of heating milk to kill germs and then cooling it is named pasteurisation after Louis Pasteur.", [747]),
(S, "In which year was Shah Waliullah of Delhi born?", ["1603", "1703", "1762", "1857"], 1,
 "Shah Waliullah Muhaddith Dehlvi was born in Delhi in 1703 and died in 1762.",
 "He is remembered as a great Islamic scholar and reformer of the 18th century in the subcontinent.", [290]),
(S, "What is the name of the house in Karachi where Quaid-e-Azam Muhammad Ali Jinnah was born?", ["Mohatta Palace", "Quaid House", "Wazir Mansion", "Flagstaff House"], 2,
 "Jinnah was born on 25 December 1876 at Wazir Mansion, Kharadar, Karachi.",
 "Wazir Mansion is now a protected national monument and a museum.", [477]),
(S, "In a class of 30 students, 2/4 are boys. What percentage of the class are girls?", ["25 percent", "40 percent", "50 percent", "60 percent"], 2,
 "2/4 of 30 is 15 boys, so girls are 30 minus 15 which is 15. Girls percentage is 15 divided by 30 times 100, which is 50 percent.",
 "2/4 is the same as 1/2, so half the class is girls.", [233]),
(S, "A man buys a pen for Rs 30 and sells it for Rs 40. What is his profit percentage?", ["10 percent", "25 percent", "30 percent", "33.33 percent"], 3,
 "Profit is 40 minus 30 which is Rs 10. Profit percentage is 10 divided by 30 times 100, which is 33.33 percent.",
 "Profit percentage is always worked out on the cost price, not the selling price.", [235, 139, 142]),
(S, "On which date did the Cabinet Mission arrive in India in 1946?", ["24 March 1946", "16 May 1946", "3 June 1947", "23 March 1940"], 0,
 "The British Cabinet Mission reached India on 24 March 1946 to discuss transfer of power.",
 "It announced its plan on 16 May 1946, proposing a loose federation with three groups of provinces.", [334]),
(S, "What is the alimentary canal?", ["The long tube of the digestive system from mouth to anus", "The tube that carries air to the lungs", "The vessel that carries blood to the heart", "The tube that carries urine from the kidneys"], 0,
 "The alimentary canal, also called the gut, runs from the mouth through the oesophagus, stomach and intestines to the anus, and digests and absorbs food.",
 "The small intestine is where most absorption of food takes place.", [429]),
(S, "In which country is the Suez Canal located and which two seas does it join?", ["Egypt; Mediterranean Sea and Red Sea", "Egypt; Red Sea and Arabian Sea", "Saudi Arabia; Red Sea and Persian Gulf", "Panama; Atlantic and Pacific"], 0,
 "The Suez Canal is an artificial waterway in Egypt joining the Mediterranean Sea in the north with the Red Sea in the south.",
 "It was opened in 1869 and shortens the sea route between Europe and Asia.", [492]),
(S, "What is the capital of Iraq?", ["Basra", "Baghdad", "Mosul", "Erbil"], 1,
 "Baghdad, on the River Tigris, is the capital and largest city of Iraq.",
 "Baghdad was the capital of the Abbasid Caliphate from 762 CE.", [439]),
(S, "Which city is called the gold capital of the world in many Pakistani textbooks?", ["Dubai", "Johannesburg", "Zurich", "Perth"], 1,
 "Johannesburg in South Africa grew from a gold rush in 1886 and is known as the City of Gold.",
 "Sources differ, as Dubai is also nicknamed the City of Gold for its gold trade.", [117]),
(S, "Who discovered that the Sun is at the centre of the solar system?", ["Ptolemy", "Nicolaus Copernicus", "Isaac Newton", "Aristotle"], 1,
 "Nicolaus Copernicus proposed the heliocentric model in 1543, placing the Sun at the centre with planets going around it.",
 "Galileo later supported this idea with telescope observations.", [655]),
(S, "Which team has won the ICC Champions Trophy the most times?", ["Australia", "Pakistan", "India", "South Africa"], 2,
 "India has won three titles: 2002 (shared with Sri Lanka), 2013 and 2025.",
 "Pakistan won the Champions Trophy once, in 2017, beating India in the final.", [639]),
(S, "Which team won the ICC Champions Trophy in 2025?", ["India", "New Zealand", "Australia", "Pakistan"], 0,
 "India beat New Zealand in the final played in Dubai on 9 March 2025.",
 "The 2025 tournament was hosted by Pakistan, but India played its matches in Dubai.", [738]),
(S, "All planets rotate on which of the following?", ["Their orbit", "Their axis", "A circle", "The Sun"], 1,
 "Every planet spins (rotates) on its own axis, while it revolves around the Sun along its orbit.",
 "Earth's rotation on its axis causes day and night.", [56]),
(S, "What is the diameter of a unit circle?", ["1", "2", "0.5", "3.14"], 1,
 "A unit circle has radius 1, so its diameter is 2 times the radius, which is 2.",
 "The circumference of a unit circle is 2 times pi.", [446]),
(S, "What is the circulatory system?", ["The system that moves blood around the body", "The system that digests food", "The system that controls breathing only", "The system that makes bones"], 0,
 "The circulatory system carries blood, oxygen and nutrients to all body parts and takes waste away.",
 "William Harvey described blood circulation in 1628.", [440]),
(S, "What are the main parts of the human circulatory system?", ["Heart, blood vessels and blood", "Lungs, liver and kidneys", "Brain, nerves and spinal cord", "Stomach, intestine and liver"], 0,
 "The heart pumps blood, blood vessels (arteries, veins, capillaries) carry it, and blood is the fluid that moves in them.",
 "Arteries carry blood away from the heart and veins bring it back.", [375]),
(S, "Who was the Chief of Army Staff of Pakistan in 1977?", ["General Yahya Khan", "General Ayub Khan", "General Zia ul Haq", "General Pervez Musharraf"], 2,
 "General Zia ul Haq was Army Chief from 1976 and took over power through martial law on 5 July 1977.",
 "He remained Army Chief until his death in August 1988.", [709]),
(S, "Complete the sentence: Practice makes us ____.", ["perfect", "lazy", "tired", "late"], 0,
 "The saying is Practice makes perfect, meaning regular practice improves skill.",
 "Another similar saying is Slow and steady wins the race.", [173]),
(S, "Choose the correct sentence.", ["She returned back from London.", "She returned from London.", "She did returned back from London.", "She returning back from London."], 1,
 "Returned already means came back, so the word back is repeated and wrong (redundant).",
 "Similar repeated phrases are reply back and revert back.", [175]),
]
